import { Fragment, useState, useEffect } from "react";
import Breadcrumbs from "@components/breadcrumbs";
import { Card, CardBody, CardHeader, Col, Label, Row } from "reactstrap";
import Select from "react-select";
import { selectThemeColors } from "@utils";
import CustomDatePicker from "../../../components/datepicker";
import { useNavigate, useSearchParams } from "react-router-dom";
import toast from "react-hot-toast";
import { Button } from "reactstrap";
import moment from "moment/moment";
import Chart from "react-apexcharts";
import { formatBytes } from "../../../helper/format_unit";
import useAccount from "../../../hooks/use_account";

const UsageAccount = () => {
  const navigate = useNavigate();
  const {
    getAccountUsageHourly,
    getAccountUsageDaily,
    accountUsageData,
    accountLoadings,
  } = useAccount();
  const [searchParams] = useSearchParams();

  const [accountIMSI, setAccountIMSI] = useState(null);
  const [tab, setTab] = useState(1);
  const [selectedCategory, setSelectedCategory] = useState({
    label: "data",
    value: "data",
  });
  const [selectedDate, setSelectedDate] = useState(null);
  const [today, setToday] = useState(null);

  // ** Chart Options
  const options = {
    chart: {
      zoom: {
        enabled: false,
      },
      parentHeightOffset: 0,
      toolbar: {
        show: false,
      },
    },
    markers: {
      strokeWidth: 4,
      strokeOpacity: 1,
      strokeColors: [
        "rgb(200,200,200)",
        "rgb(200,200,200)",
        "rgb(200,200,200)",
        "rgb(200,200,200)",
        "rgb(200,200,200)",
        "rgb(200,200,200)",
        "rgb(200,200,200)",
      ],
      colors: [
        "#07274E",
        "#ea5455",
        "#ea5455",
        "#00cfe8",
        "#ff9f43",
        "#28c76f",
        "#ede209",
      ],
    },
    dataLabels: {
      enabled: false,
    },
    stroke: {
      curve: "straight",
    },
    colors: [
      "#07274E",
      "#ea5455",
      "#ea5455",
      "#00cfe8",
      "#ff9f43",
      "#28c76f",
      "#ede209",
    ],
    grid: {
      xaxis: {
        lines: {
          show: true,
        },
      },
    },
    legend: {
      show: true,
      horizontalAlign: "center",
      fontSize: "12px",
    },
    xaxis: {
      categories: accountUsageData.categories,
      labels: {
        show: true,
        style: {
          colors: [],
          fontSize: "10.5px",
        },
        formatter: (value) => {
          if (tab == 1) {
            return moment(value).utc().format("HH:mm");
          } else {
            return moment(value).format("MM/DD");
          }
        },
        offsetX: 2,
      },
    },
    yaxis: {
      opposite: "rtl",
      labels: {
        show: true,
        formatter: (value) => {
          if (selectedCategory.value == "data") {
            return formatBytes(value);
          } else {
            const hours = Math.floor(value / 3600);
            const minutes = Math.floor((value % 3600) / 60);
            const secs = value % 60;

            return [
              hours.toString().padStart(2, "0"),
              minutes.toString().padStart(2, "0"),
              secs.toString().padStart(2, "0"),
            ].join(":");
          }
        },
      },
    },
    tooltip: {
      enabled: true,
      onDatasetHover: {
        highlightDataSeries: false,
      },
      x: {
        show: true,
        title: {
          formatter: (seriesName) => seriesName,
        },
      },
      y: {
        formatter: undefined,
        title: {
          formatter: (seriesName) => seriesName,
        },
      },
    },
  };

  useEffect(() => {
    setSelectedDate({
      year: parseInt(moment().format("YYYY")),
      month: parseInt(moment().format("MM")),
      day: parseInt(moment().format("DD")),
    });
    setToday({
      year: parseInt(moment().format("YYYY")),
      month: parseInt(moment().format("MM")),
      day: parseInt(moment().format("DD")),
    });
    let account_IMSI = searchParams.get("account_IMSI");
    if (account_IMSI) {
      setAccountIMSI(account_IMSI);
      getAccountUsageHourly(
        {
          year: parseInt(moment().format("YYYY")),
          month: parseInt(moment().format("MM")),
          day: parseInt(moment().format("DD")),
        },
        selectedCategory,
        account_IMSI
      );
    } else {
      navigate("/accounts/all");
      toast.error("Account not found!");
    }
  }, []);

  return (
    <Fragment>
      <Breadcrumbs
        title="Account Usage"
        data={[{ title: "Accounts" }, { title: "Create Usage" }]}
      />
      {/* filterbar */}
      <Card>
        <CardBody>
          <Row>
            {/* Category */}
            <Col xs="12" sm="6" md="4" className={"mb-1"}>
              <Label>Category</Label>
              <Select
                isClearable={false}
                theme={selectThemeColors}
                closeMenuOnSelect={true}
                placeholder="select category"
                maxMenuHeight={120}
                options={[
                  { label: "data", value: "data" },
                  { label: "voice", value: "voice" },
                  { label: "video", value: "video" },
                ]}
                className={`react-select`}
                value={selectedCategory}
                onChange={(value) => {
                  setSelectedCategory(value);
                  if (tab == 1) {
                    getAccountUsageHourly(selectedDate, value, accountIMSI);
                  } else {
                    getAccountUsageDaily(selectedDate, value, accountIMSI);
                  }
                }}
                classNamePrefix="select"
                id="category"
                name="category"
              />
            </Col>
            {/* Start date */}
            <Col xs="12" sm="6" md="4" className={"mb-1"}>
              <Label>Start date</Label>
              <CustomDatePicker
                value={selectedDate}
                onChange={(value) => {
                  setSelectedDate(value);
                  if (tab == 1) {
                    getAccountUsageHourly(value, selectedCategory, accountIMSI);
                  } else {
                    getAccountUsageDaily(value, selectedCategory, accountIMSI);
                  }
                }}
                inputPlaceholder="Select date"
                calendarPopperPosition={"bottom"}
                maximumDate={today}
              />
            </Col>
          </Row>
        </CardBody>
      </Card>
      {/* chart */}
      <Card>
        <CardHeader className={"d-flex justify-content-start border-bottom"}>
          <Button
            color="primary"
            outline={tab == 2 ? true : false}
            onClick={() => {
              setTab(1);
              getAccountUsageHourly(
                selectedDate,
                selectedCategory,
                accountIMSI
              );
            }}
            style={{ marginRight: 16 }}
          >
            Hourly
          </Button>
          <Button
            color="primary"
            outline={tab == 1 ? true : false}
            onClick={() => {
              setTab(2);
              getAccountUsageDaily(selectedDate, selectedCategory, accountIMSI);
            }}
          >
            Daily
          </Button>
        </CardHeader>
        <CardBody>
          <Chart
            options={options}
            series={[
              {
                name: "Usage",
                data: accountUsageData.data,
              },
            ]}
            type="line"
            height={400}
          />
        </CardBody>
      </Card>
    </Fragment>
  );
};
export default UsageAccount;
